#!/usr/bin/env python3
from __future__ import annotations
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
BIRD=ROOT/'Logo'/'Oiseau'

def between(text,start,end,repl):
    i=text.find(start); j=text.find(end,i)
    if i<0 or j<0: raise RuntimeError(f'marker missing: {start!r} / {end!r}')
    return text[:i]+repl+text[j:]

build_path=BIRD/'build_bird.py'
build=build_path.read_text(encoding='utf-8')
if 'def display_pose(' not in build:
    build=build.replace('def wing_geometry(model: dict, pose: dict, side: str) -> dict:\n', '''def display_pose(model: dict, side: str) -> dict:\n    pose = dict(model["wing"]["display_pose"])\n    pose["span_scale"] *= model["wing"][f"{side}_scale"]\n    pose["chord_scale"] *= math.sqrt(model["wing"][f"{side}_scale"])\n    return pose\n\n\ndef wing_geometry(model: dict, pose: dict, side: str) -> dict:\n''')
pygeom='''def _transform_by_bone(point, rest_a, rest_b, current_a, current_b):\n    rest_vector=sub(rest_b,rest_a); current_vector=sub(current_b,current_a)\n    rest_length=norm(rest_vector); current_length=norm(current_vector)\n    if rest_length < 1e-9: raise ValueError("degenerate reference wing bone")\n    scale=current_length/rest_length\n    angle=math.atan2(current_vector[1],current_vector[0])-math.atan2(rest_vector[1],rest_vector[0])\n    local=sub(point,rest_a); c=math.cos(angle); s=math.sin(angle)\n    return add(current_a,(scale*(local[0]*c-local[1]*s),scale*(local[0]*s+local[1]*c)))\n\ndef _skin_point(point,weights,rest_joints,current_joints):\n    if abs(sum(weights)-1)>1e-6: raise ValueError("wing skin weights must sum to one")\n    result=(0.0,0.0)\n    for index,weight in enumerate(weights):\n        transformed=_transform_by_bone(point,rest_joints[index],rest_joints[index+1],current_joints[index],current_joints[index+1])\n        result=add(result,mul(transformed,weight))\n    return result\n\ndef wing_geometry(model: dict, pose: dict, side: str) -> dict:\n    wing=model["wing"]; shoulder=tuple(wing["shoulders"][side])\n    scale=pose["span_scale"]*wing[f"{side}_scale"] if pose.get("absolute_scale") else pose["span_scale"]\n    l1,l2,l3=[length*scale for length in wing["segment_lengths"]]\n    a1=math.radians(pose["stroke_deg"]); a2=a1+math.radians(pose["elbow_deg"]); a3=a2+math.radians(pose["wrist_deg"])\n    s=shoulder; e=add(s,(l1*math.cos(a1),l1*math.sin(a1))); w=add(e,(l2*math.cos(a2),l2*math.sin(a2))); tip=add(w,(l3*math.cos(a3),l3*math.sin(a3)))\n    joints=[s,e,w,tip]; reference=wing.get("reference_mesh")\n    if reference:\n        ref_shoulder=tuple(reference["joints"][0]); perspective=wing[f"{side}_scale"]\n        map_ref=lambda point:add(shoulder,mul(sub(tuple(point),ref_shoulder),perspective))\n        rest_joints=[map_ref(point) for point in reference["joints"]]\n        rest_boundary=[map_ref(point) for point in reference["boundary"]]\n        rest_core=map_ref(reference["core"])\n        boundary=[_skin_point(point,weights,rest_joints,joints) for point,weights in zip(rest_boundary,reference["boundary_weights"])]\n        core=_skin_point(rest_core,reference["core_weights"],rest_joints,joints)\n        return {"boundary":boundary,"core":core,"joints":joints}\n    tangents=[sub(e,s),add(unit(sub(e,s)),unit(sub(w,e))),add(unit(sub(w,e)),unit(sub(tip,w))),sub(tip,w)]\n    normals=[normal(vector) for vector in tangents]; widths=[value*pose["chord_scale"] for value in wing["chords"]]\n    lead=wing["leading_fraction"]\n    leading=[sub(point,mul(nrm,width*lead)) for point,nrm,width in zip(joints,normals,widths)]\n    trailing=[add(point,mul(nrm,width*(1-lead))) for point,nrm,width in zip(joints,normals,widths)]\n    boundary=[leading[0],leading[1],leading[2],tip,trailing[2],trailing[1],trailing[0]]\n    core=(.18*s[0]+.33*e[0]+.34*w[0]+.15*tip[0],.18*s[1]+.33*e[1]+.34*w[1]+.15*tip[1])\n    return {"boundary":boundary,"core":core,"joints":joints}\n\n\n'''
build=between(build,'def wing_geometry(model: dict, pose: dict, side: str) -> dict:\n','def sample_clip(model: dict, clip_name: str, phase: float) -> dict:\n',pygeom)
build=build.replace('        pose_far = periodic_pose(model, 0.18, "far")\n        pose_near = periodic_pose(model, 0.18, "near")','        pose_far = display_pose(model, "far")\n        pose_near = display_pose(model, "near")')
build_path.write_text(build,encoding='utf-8')

js_path=BIRD/'bird-animation.js'; js=js_path.read_text(encoding='utf-8')
jsgeom='''  function transformByBone(point, restA, restB, currentA, currentB) {\n    const restVector=sub(restB,restA); const currentVector=sub(currentB,currentA);\n    const restLength=length(restVector); const currentLength=length(currentVector);\n    if (restLength < 1e-9) throw new Error('Percolia reference wing bone is degenerate');\n    const scale=currentLength/restLength;\n    const angle=Math.atan2(currentVector[1],currentVector[0])-Math.atan2(restVector[1],restVector[0]);\n    const local=sub(point,restA); const c=Math.cos(angle); const s=Math.sin(angle);\n    return add(currentA,[scale*(local[0]*c-local[1]*s),scale*(local[0]*s+local[1]*c)]);\n  }\n\n  function skinPoint(point, weights, restJoints, currentJoints) {\n    return weights.reduce((result,weight,index)=>add(result,mul(transformByBone(point,restJoints[index],restJoints[index+1],currentJoints[index],currentJoints[index+1]),weight)),[0,0]);\n  }\n\n  function wingGeometry(model, pose, side) {\n    const wing=model.wing; const shoulder=wing.shoulders[side];\n    const lengths=wing.segment_lengths.map((value)=>value*pose.span_scale);\n    const a1=pose.stroke_deg*RAD; const a2=a1+pose.elbow_deg*RAD; const a3=a2+pose.wrist_deg*RAD;\n    const s=shoulder.slice(); const e=add(s,[lengths[0]*Math.cos(a1),lengths[0]*Math.sin(a1)]);\n    const w=add(e,[lengths[1]*Math.cos(a2),lengths[1]*Math.sin(a2)]);\n    const tip=add(w,[lengths[2]*Math.cos(a3),lengths[2]*Math.sin(a3)]); const joints=[s,e,w,tip];\n    const reference=wing.reference_mesh;\n    if (reference) {\n      const refShoulder=reference.joints[0]; const perspective=wing[`${side}_scale`];\n      const mapRef=(point)=>add(shoulder,mul(sub(point,refShoulder),perspective));\n      const restJoints=reference.joints.map(mapRef); const restBoundary=reference.boundary.map(mapRef); const restCore=mapRef(reference.core);\n      const boundary=restBoundary.map((point,index)=>skinPoint(point,reference.boundary_weights[index],restJoints,joints));\n      const core=skinPoint(restCore,reference.core_weights,restJoints,joints);\n      return {boundary,core,joints};\n    }\n    const tangents=[sub(e,s),add(unit(sub(e,s)),unit(sub(w,e))),add(unit(sub(w,e)),unit(sub(tip,w))),sub(tip,w)];\n    const normals=tangents.map(normal); const widths=wing.chords.map((value)=>value*pose.chord_scale);\n    const leading=joints.map((point,index)=>sub(point,mul(normals[index],widths[index]*wing.leading_fraction)));\n    const trailing=joints.map((point,index)=>add(point,mul(normals[index],widths[index]*(1-wing.leading_fraction))));\n    const boundary=[leading[0],leading[1],leading[2],tip,trailing[2],trailing[1],trailing[0]];\n    const core=[.18*s[0]+.33*e[0]+.34*w[0]+.15*tip[0],.18*s[1]+.33*e[1]+.34*w[1]+.15*tip[1]];\n    return {boundary,core,joints};\n  }\n\n'''
js=between(js,'  function wingGeometry(model, pose, side) {\n','  function collectWing(root, side) {\n',jsgeom)
js=js.replace("stroke_deg: stroke + (side === 'far' ? -5.5 : 0),","stroke_deg: stroke + (side === 'far' ? -2.0 : 0),")
js=js.replace("elbow_deg: elbow + (side === 'far' ? 2 : 0),","elbow_deg: elbow + (side === 'far' ? 1 : 0),")
js=js.replace("wrist_deg: wrist + (side === 'far' ? 3 : 0),","wrist_deg: wrist + (side === 'far' ? 1.5 : 0),")
js_path.write_text(js,encoding='utf-8')
Path(__file__).unlink(); print('reference wing mesh installed')
